// folia/sources/netease/core/index.ts
var createSource = (env) => {
  setNeteaseEnv(env);
  disposeSource();
  return createNeteaseSource();
};
var disposeSource = () => {
  resetNeteaseTransport();
  resetNeteaseLocalService();
  resetNeteaseProviderRuntimeCache();
};

// folia/sources/netease/client/index.ts
function activate2(folium) {
  let handle = null;
  handle = folium.sources.register(createSource({
    modId: folium.modId,
    call: (name, ...args) => folium.rpc.call(name, ...args),
    text: (key, params) => folium.i18n.key(key, params),
    translate: (key, params) => folium.i18n.text(key, params),
    error: (code, message, details) => folium.sources.error(code, message, details),
    isPureMusicText: (text2) => folium.lyrics.isPureMusicText(text2),
    pageStore: (sourceId) => folium.sources.pageStore(sourceId),
    // A startup failure of the API is told once (neteaseLocalService.ts).
    notify: (notice) => handle?.notify(notice)
  }));
  folium.rpc.on("status", (status) => {
    noteNeteaseBackendStatus(status ?? null);
  });
  return () => {
    handle = null;
    disposeSource();
  };
}

